const PUZZLES = [{"t":"Art · Renaissance","l":1,"c":"Leonardo da Vinci","a":["Leonardo da Vinci","Leonardo","da Vinci","Leonardo DaVinci","Leonardo di ser Piero da Vinci"],"s":["The Mona Lisa was painted by","Michelangelo","in the early 1500s,","and it now hangs in the Louvre."],"w":"It’s Leonardo da Vinci. Michelangelo was across town sculpting David, but he never painted her."},{"t":"Ancient Egypt","l":3,"c":"the Egyptians","a":["Egyptians","the Egyptians","ancient Egyptians"],"s":["Built around 2560 BCE","as a tomb for the pharaoh Khufu,","the Great Pyramid of Giza","is the work of the Romans."],"w":"Egyptians built it. Rome would not be founded for another two thousand years."},{"t":"Geography","l":1,"c":"Nepal and China","a":["Nepal and China","Nepal and China (Tibet)","Nepal and Tibet","China","Tibet"],"s":["Mount Everest sits on the border between","Nepal and India,","and its summit rises","about 8,849 meters above sea level."],"w":"Nepal and China, on the Tibetan side. India borders Nepal, but nowhere near Everest."},{"t":"US History","l":0,"c":"George Washington","a":["George Washington","Washington"],"s":["Thomas Jefferson","was the first President of the United States,","taking the oath of office","in New York City in 1789."],"w":"Washington took the oath in April 1789, in New York, then the capital. Jefferson was the third president."},{"t":"Modern History","l":2,"c":"Germany and Japan","a":["Germany and Japan","Japan","Japan and Germany"],"s":["World War II ended in 1945","with the surrenders of","Germany and Italy,","followed by years of rebuilding."],"w":"Germany surrendered in May 1945, Japan that September. Italy had switched sides and surrendered back in 1943."},{"t":"Chemistry","l":3,"c":"Au","a":["Au","AU","au"],"s":["Named for its Latin name, aurum,","gold","carries the chemical symbol","Go."],"w":"Au, from the Latin aurum. “Go” is not on the periodic table, however excellent a board game it is."},{"t":"Geography","l":0,"c":"the Pacific","a":["Pacific","the Pacific","Pacific Ocean","the Pacific Ocean"],"s":["The Atlantic Ocean","is the largest ocean on Earth,","covering roughly a third","of the planet’s surface."],"w":"The Pacific is the largest, about 165 million square kilometers, more than double the Atlantic."},{"t":"Physics","l":3,"c":"per second","a":["second","seconds","sec","s","per second"],"s":["Nothing is faster than light,","which races through empty space","at roughly 300,000 kilometers","per hour."],"w":"About 300,000 km per second. At 300,000 km per hour, sunlight would take roughly three weeks to reach Earth."},{"t":"Music","l":3,"c":"Liverpool","a":["Liverpool"],"s":["Before conquering recorded music,","the Beatles","got their start in 1960 in","London."],"w":"Liverpool. The Fab Four were Merseyside lads; London came later, once the records sold."},{"t":"US History","l":1,"c":"France","a":["France","the French","french"],"s":["Dedicated in 1886,","the Statue of Liberty was a gift from","Britain","to the United States."],"w":"A gift from France, sculpted by Bartholdi, with the iron frame engineered by a young Gustave Eiffel."},{"t":"Biology","l":0,"c":"chimpanzees","a":["chimpanzees","chimps","bonobos","chimpanzees and bonobos","the chimpanzees"],"s":["Bananas","are our closest living relatives,","sharing about 98.8%","of human DNA."],"w":"Chimpanzees (and bonobos), at about 98.8%. Bananas share roughly 40–60% of our gene families, oddly high, but no relative."},{"t":"Geography","l":3,"c":"the Atlantic","a":["Atlantic","the Atlantic","Atlantic Ocean","the Atlantic Ocean"],"s":["Flowing from the Andes across South America,","Earth’s largest river by volume,","the Amazon","empties into the Pacific Ocean."],"w":"The Atlantic. East of the Andes there is a continent in the way; the Pacific is the far side."},{"t":"Space","l":0,"c":"Yuri Gagarin","a":["Yuri Gagarin","Gagarin"],"s":["Neil Armstrong","was the first human in space,","launched by the Soviet Union","in April 1961."],"w":"Yuri Gagarin, aboard Vostok 1, April 12, 1961. Armstrong’s big first came eight years later, on the Moon."},{"t":"Tech","l":1,"c":"CERN","a":["CERN","cern"],"s":["In 1989, Tim Berners-Lee invented the World Wide Web","while working at MIT,","and later gave it away","royalty-free."],"w":"CERN, the particle physics lab in Geneva. A good reminder that the Web’s birthplace was a physics lab, not a university."},{"t":"World","l":0,"c":"the yen","a":["yen","the yen"],"s":["The yuan","is the official currency of Japan,","divided into 100 sen,","and anchored by the Bank of Japan."],"w":"The yen (¥). The yuan is China’s currency; close neighbors, very different bank accounts."},{"t":"Biology","l":3,"c":"oxygen","a":["oxygen","O2","the oxygen"],"s":["Photosynthesis lets plants","turn water and carbon dioxide into sugar,","a process that releases","carbon dioxide."],"w":"Oxygen, the waste product of photosynthesis, and the reason you’re alive to click this."},{"t":"Modern History","l":3,"c":"1989","a":["1989","in 1989","November 1989"],"s":["After dividing East from West Berlin for 28 years,","the Berlin Wall finally came down","in November","of 1961."],"w":"November 9, 1989. It was built in 1961; that year was its birthday, not its funeral."},{"t":"History","l":3,"c":"New Zealand","a":["New Zealand","NZ","Aotearoa"],"s":["The first country to give women the vote","in national elections,","back in 1893,","was Australia."],"w":"New Zealand, 1893. Australia followed in 1902, though Aboriginal women there waited until 1962."},{"t":"Space","l":0,"c":"Jupiter","a":["Jupiter","jupiter"],"s":["Saturn","is the largest planet in our solar system,","more than twice the mass","of every other planet combined."],"w":"Jupiter. Saturn’s rings get the attention; Jupiter gets the crown."},{"t":"Sports","l":3,"c":"the National Football League","a":["NFL","the NFL","National Football League","the National Football League","NFL (the National Football League)"],"s":["First played in 1967,","the Super Bowl is the annual championship game","of the","National Basketball Association."],"w":"The NFL. The NBA’s big night is called the Finals. Super Bowl I was played in January 1967."},{"t":"Nature","l":1,"c":"the Antarctic","a":["Antarctic","the Antarctic","Antarctica","Southern Hemisphere","the Southern Hemisphere"],"s":["Penguins are native to the","Arctic,","where their predators include","leopard seals and orcas."],"w":"The Southern Hemisphere, mostly Antarctica. A penguin and a polar bear have never met in the wild."},{"t":"US History","l":0,"c":"four","a":["four","4"],"s":["Five US presidents","have their faces carved into Mount Rushmore,","in the Black Hills","of South Dakota."],"w":"Four: Washington, Jefferson, Theodore Roosevelt, and Lincoln."},{"t":"Medieval","l":3,"c":"France","a":["France","the French"],"s":["The Hundred Years’ War,","fought on and off from 1337 to 1453,","pitted England against","Spain."],"w":"France, for 116 years give or take, which is why the name undersells it slightly."},{"t":"British History","l":3,"c":"1666","a":["1666"],"s":["The Great Fire of London raged for four days","in September,","destroying much of the medieval city","in 1665."],"w":"September 1666. The year 1665 belonged to the Great Plague, a truly terrible decade for London."},{"t":"Science","l":0,"c":"Alexander Fleming","a":["Alexander Fleming","Fleming"],"s":["Jonas Salk","discovered penicillin,","the world’s first antibiotic,","back in 1928."],"w":"Alexander Fleming noticed the mold in 1928. Salk’s masterpiece came in 1955: the polio vaccine."},{"t":"Space","l":3,"c":"27 days","a":["27 days","27.3 days","a month","month","27","about 27 days","29 days","29.5 days"],"s":["At an average distance of 384,400 km,","the Moon completes one orbit of Earth","roughly every","24 hours."],"w":"About 27.3 days per orbit, and about 29.5 days between full moons. We see it nightly because Earth spins, not because the Moon races."},{"t":"Food","l":1,"c":"beans","a":["beans","seeds","coffee beans","the beans","pits"],"s":["Coffee is brewed from the roasted","leaves","of the Coffea plant,","native to Ethiopia."],"w":"The roasted seeds, or “beans,” of the coffee cherry. Leaves get you tea."},{"t":"Geography","l":0,"c":"Ottawa","a":["Ottawa"],"s":["Toronto","is the capital of Canada,","a city chosen by Queen Victoria","in 1857."],"w":"Ottawa, picked in 1857 as a compromise between the big rivals. Toronto is the largest city, but size does not win you the capital."},{"t":"US Geography","l":2,"c":"Juneau","a":["Juneau"],"s":["Alaska, the largest US state by area,","keeps its capital in","Anchorage,","which travelers reach only by boat or plane."],"w":"Juneau, the only US state capital you cannot drive to. Anchorage is the biggest city, not the boss."},{"t":"Literature","l":0,"c":"Baker Street","a":["Baker Street","Baker"],"s":["221B Oxford Street","is the famous London home","of the fictional detective","Sherlock Holmes."],"w":"221B Baker Street, today the Sherlock Holmes Museum. Oxford Street is the one with the shops."},{"t":"Nature","l":1,"c":"crows","a":["crows","crow"],"s":["A group of","lions","is called","a murder."],"w":"Crows: a murder of crows. Lions gather in prides."},{"t":"Geography","l":3,"c":"the Mediterranean","a":["Mediterranean","the Mediterranean","Mediterranean Sea","the Mediterranean Sea"],"s":["After flowing north for over 6,600 km,","the Nile, the longest river in Africa,","empties into the","Red Sea."],"w":"The Mediterranean, via the famous delta. The Red Sea is the one Moses is famous for."},{"t":"Painters","l":1,"c":"Dutch","a":["Dutch","Netherlandish","from the Netherlands","a Dutchman","Holland"],"s":["Vincent van Gogh was a","Spanish","painter who sold almost nothing in his lifetime,","and whose Sunflowers now hang in museums around the world."],"w":"Dutch, born in Zundert in the Netherlands. He did his greatest work in the south of France, but Spain never had him."},{"t":"First Flight","l":3,"c":"1903","a":["1903","in 1903","December 1903","in December 1903"],"s":["Orville and Wilbur Wright made the first powered, controlled airplane flight","on the dunes of Kitty Hawk, North Carolina,","on a cold December morning in","1905."],"w":"December 17, 1903. The brothers flew four times that morning; the longest hop lasted 59 seconds, and the century of flight started there."},{"t":"Napoleon","l":2,"c":"Belgium","a":["Belgium","in Belgium","the Netherlands","the Low Countries"],"s":["Napoleon met his final defeat at Waterloo,","a name the world now uses for any last stand,","in France,","just south of Brussels."],"w":"Waterloo is in Belgium, south of Brussels. In 1815 it lay in the United Kingdom of the Netherlands; France has never owned it."},{"t":"Invention","l":1,"c":"Alexander Graham Bell","a":["Alexander Graham Bell","Alexander Bell","Graham Bell","Bell"],"s":["The telephone was patented by","Thomas Edison","in 1876,","the same year the Sioux won at the Little Bighorn."],"w":"Alexander Graham Bell, whose patent was granted March 7, 1876. Edison was busy with the phonograph, which he got around to the following year."},{"t":"England","l":2,"c":"King John","a":["King John","John","John Lackland"],"s":["In the summer of 1215, on a meadow by the Thames called Runnymede, England’s barons forced a charter of rights onto the crown,","sealed under protest by","King Henry VIII,","and known to history as Magna Carta."],"w":"King John put his seal to Magna Carta in June 1215. Henry VIII was born 294 years too late, and would have hated the whole idea."},{"t":"Disasters","l":2,"c":"the Atlantic Ocean","a":["the Atlantic","the Atlantic Ocean","the North Atlantic","Atlantic"],"s":["Four days out of Southampton on her maiden voyage, the RMS Titanic struck an iceberg and sank,","with more than 1,500 lives lost,","in the Pacific Ocean,","on the night of April 14, 1912."],"w":"The North Atlantic, roughly 400 miles south of Newfoundland. The Pacific never entered into it; she was on the New York run."},{"t":"Sport","l":1,"c":"Athens","a":["Athens","in Athens","Greece","in Greece"],"s":["The first modern Olympic Games opened in","Rome,","in 1896,","before a crowd of tens of thousands."],"w":"Athens, in the rebuilt Panathenaic Stadium, in April 1896. Rome had to wait until 1960 for its Games."},{"t":"The Norse","l":3,"c":"Leif Erikson","a":["Leif Erikson","Leif Ericson","Leif","Leifr","Leif the Lucky"],"s":["Around the year 1000, Norse voyagers crossed to North America and wintered at a shore they called Vinland,","a story the sagas tell and that a Newfoundland site confirms,","a voyage led by","Erik the Red."],"w":"Leif Erikson, Erik the Red’s son. The father spent his years colonizing Greenland and feuding with neighbors; the son did the exploring."},{"t":"Architecture · Greece","l":3,"c":"Athens","a":["Athens","in Athens","Greece","in Greece","Athens, Greece"],"s":["The Parthenon, built in the fifth century BCE as a temple to Athena,","has stood over the city beneath it for two and a half thousand years,","and it looks out today from the heart of","Rome."],"w":"Athens. The Parthenon has crowned the Acropolis since the days of Pericles and has never moved an inch. Rome has plenty of ruins of its own; this one is Greek."},{"t":"Medicine · 1967","l":3,"c":"Cape Town","a":["Cape Town","South Africa","in Cape Town","in South Africa","Cape Town, South Africa"],"s":["The first successful human heart transplant was led by surgeon Christiaan Barnard","on December 3, 1967,","at Groote Schuur Hospital in","New York."],"w":"Cape Town, South Africa. The patient, Louis Washkansky, lived eighteen days with a heart donated by a young woman killed in a car crash. American centers followed within weeks."},{"t":"Prizes · Alfred Nobel","l":2,"c":"dynamite","a":["dynamite","of dynamite","the dynamite"],"s":["The Nobel Prizes are funded by the fortune of Alfred Nobel,","the Swedish inventor","of the telegraph,","whose will set his wealth aside to reward the greatest benefit to humankind."],"w":"Dynamite, patented in 1867, built the fortune. The story goes that Nobel rewrote his will after reading a prematurely published obituary that called him a merchant of death."},{"t":"Medieval · The Bayeux Tapestry","l":2,"c":"England","a":["England","in England","Kent","in Kent","southern England"],"s":["The Bayeux Tapestry, which pictures the Norman Conquest in stitched scenes,","was worked by embroiderers","in Normandy,","within a few years of the battle of 1066."],"w":"England, most likely in a Kent workshop. The consensus rests on the tapestry’s English spellings and its kinship with Anglo-Saxon needlework. It is displayed in France today, but the stitching is judged English."},{"t":"Nature · Reefs","l":3,"c":"Australia","a":["Australia","Queensland","off Australia","off Queensland","northeastern Australia"],"s":["The Great Barrier Reef is the largest structure built by living things,","so huge that astronauts can see it from orbit,","and it runs for over 2,000 kilometers off the coast of","Brazil."],"w":"Australia. The reef lies off Queensland in the Coral Sea and has never been anywhere near Brazil, which keeps its own reefs in the Atlantic."},{"t":"Russia · The Last Tsar","l":3,"c":"1917","a":["1917","in 1917","March 1917","February 1917"],"s":["The last Russian emperor, Nicholas II,","was swept from his throne by the revolution","of","1905."],"w":"1917. The February Revolution took the throne, the October Revolution took the country, and the family paid the price the next year. The rising of 1905 only rattled the autocracy."},{"t":"Art · The Louvre","l":3,"c":"77 centimeters","a":["77 centimeters","77cm","0.77 meters","29 inches","about 77 centimeters","30 inches"],"s":["The Mona Lisa, the most famous painting on Earth,","hangs in the Louvre behind bulletproof glass,","and measures just under","four meters."],"w":"Just 77 by 53 centimeters. Visitors expecting a wall-sized masterpiece find a portrait smaller than a sheet of newsprint, which is why the crowd leans in and the guards look tired."},{"t":"Exploration · The Poles","l":3,"c":"Roald Amundsen","a":["Roald Amundsen","Amundsen","the Norwegian","Roald Amundsen, a Norwegian"],"s":["The geographic South Pole was first reached","in December 1911,","by the explorer","Robert Falcon Scott."],"w":"Roald Amundsen, who planted the Norwegian flag on December 14, 1911. Scott’s party arrived five weeks later, in January 1912, and died on the march back to the coast."},{"t":"Invention · Paper","l":1,"c":"the Chinese","a":["the Chinese","China","the Chinese,","in China","Chinese"],"s":["Paper, the quiet engine of civilization, was first made by","the Egyptians,","who pounded bark, hemp, and rags into sheets,","a craft later carried west along the Silk Road."],"w":"Papyrus is not paper. True paper, made by pulping plant fibers and matting them into a sheet, was invented in Han dynasty China, traditionally credited to the court official Cai Lun around 105 CE, and reached Europe more than a thousand years later."},{"t":"France · The Eiffel Tower","l":2,"c":"the 1889 World’s Fair","a":["the 1889 World’s Fair","the World’s Fair","World’s Fair","the Exposition Universelle","the 1889 Exposition Universelle","the Paris Exposition of 1889"],"s":["The Eiffel Tower, the iron giant of Paris,","was built in 1889 by Gustave Eiffel’s firm","as a gateway arch for the Olympic Games,","and was meant to stand for only twenty years."],"w":"It was the centerpiece of the Exposition Universelle of 1889, the world’s fair marking the centenary of the French Revolution. And it truly was licensed for twenty years, saved at first by its value as a radio antenna."},{"t":"Greece · Alexander the Great","l":1,"c":"Pella","a":["Pella","in Pella","Macedonia","in Macedonia","Pella, Macedonia"],"s":["Alexander the Great, conqueror of the Persian Empire,","was born in Athens in 356 BCE,","was tutored by Aristotle as a boy,","and set out at twenty to change the world."],"w":"He was born at Pella, the capital of the kingdom of Macedon, in 356 BCE. Athens was a rival power that his father Philip II spent years battering into submission; Alexander was a Macedonian to the bone."},{"t":"Pets · The Goldfish","l":2,"c":"months","a":["months","several months","months at a time","at least months","about three months"],"s":["The goldfish, forgetful star of every joke,","can hold a new memory for","three seconds,","before the tank fades to blank again."],"w":"Goldfish learn mazes, remember feeding schedules for months, and can tell their keepers apart. Experiments reaching back decades show memories lasting at least three months, and the three-second slander has failed every test it has ever faced."},{"t":"America · The Constitution","l":3,"c":"1787","a":["1787","in 1787","September 1787","1787,"],"s":["The Constitution of the United States, the supreme law of the republic,","was drafted at a convention in Philadelphia","by delegates arguing through a sweltering summer","in 1776."],"w":"The Constitution was signed on September 17, 1787. The year 1776 belongs to the Declaration of Independence, a different document signed in the same room eleven years earlier; the Constitution took effect in 1789, after ratification."},{"t":"Empires · The Aztec","l":1,"c":"North America","a":["North America","in North America","Mexico","in Mexico"],"s":["The Aztec Empire, with its capital on a lake,","flourished in South America","for nearly a century,","until Cortés arrived in 1519."],"w":"The Aztec world sat in the valley of Mexico, on the continent of North America as geographers draw it. Tenochtitlan’s ruins lie beneath the middle of Mexico City, some 2,200 meters above sea level."},{"t":"Plants · The Banana","l":1,"c":"an herb","a":["an herb","a herb","herbs","herbaceous plants","the largest herb"],"s":["The banana plant, staple of supermarkets and lunchboxes,","is a tree","that bears its fruit in hanging bunches","on tropical plantations worldwide."],"w":"The banana is a giant herb of the genus Musa: no woody trunk, just tightly packed leaf stalks, and the plant dies back after fruiting. It is often called the largest herbaceous plant on Earth, and the biggest of them can top seven meters."},{"t":"Geology · The Diamond","l":1,"c":"carbon","a":["carbon","pure carbon","from carbon","of carbon"],"s":["Diamonds, the hardest natural substance known, are made of","coal","crystallized under crushing heat and pressure","deep in the Earth’s mantle over billions of years."],"w":"Diamonds grow from carbon in the mantle, but not from coal: most diamonds are far older than every land plant, and coal seams simply cannot sink a hundred kilometers down. The coal-to-diamond recipe is a cartoon version of geology."},{"t":"Invention · The Steam Engine","l":2,"c":"Thomas Newcomen","a":["Thomas Newcomen","Newcomen","Newcomen’s engine","Thomas Newcomen’s engine"],"s":["The first practical steam engine, built to drain deep mines,","appeared in 1712 as the invention of","James Watt,","an English ironmonger whose engine pumped coal mines for half a century."],"w":"Thomas Newcomen’s atmospheric engine was pumping mines from 1712, two generations before Watt rebuilt it with a separate condenser in the 1760s. Watt made the steam engine efficient; Newcomen made it work."},{"t":"Printing · Movable Type","l":2,"c":"China","a":["China","the Chinese","eleventh-century China","Chinese","in China"],"s":["Movable type, printing from cast and arranged letters,","first appeared in","fifteenth-century Germany,","and was perfected by Johannes Gutenberg at Mainz."],"w":"Bi Sheng carved ceramic movable type in China in the 1040s, four centuries before Mainz; Korea was casting it in metal and printing books with it a century before Gutenberg. Europe’s press was revolutionary, but the idea had long since existed in East Asia."},{"t":"Egypt · Cleopatra","l":0,"c":"Greek","a":["Greek","a Greek","Macedonian","a Macedonian","Greek Macedonian"],"s":["Egyptian by blood,","Cleopatra VII was the last pharaoh of Egypt,","enthroned in Alexandria above a Greek-speaking court,","until Rome absorbed her kingdom in 30 BCE."],"w":"The Ptolemies were Macedonian Greeks descended from Alexander’s general Ptolemy, and they kept the bloodline in the family for ten generations. Cleopatra was the first of her line to bother learning Egyptian; her court spoke Greek."},{"t":"Space · The Hottest Planet","l":2,"c":"hotter","a":["hotter","hotter than Mercury","even hotter","hotter than scorched Mercury"],"s":["Venus hides beneath a shroud of pale cloud,","orbiting second from the Sun, yet stays","cooler","than scorched Mercury, which shines bright enough to be mistaken for a star."],"w":"Venus is the hottest planet, around 465 degrees Celsius day and night, pole to pole. Its carbon dioxide atmosphere holds the heat, while Mercury, with no air worth the name, swings from roasting to freezing every two months."},{"t":"Nature · The Tallest Mountain","l":3,"c":"Mauna Kea","a":["Mauna Kea","Mauna Kea in Hawaii","Hawaii’s Mauna Kea"],"s":["Measured from base to peak rather than from sea level,","the tallest mountain on Earth","rises more than ten kilometers of continuous slope,","and it is Mount Everest."],"w":"Mauna Kea rises over 10,000 meters from the Pacific floor, most of it underwater; Everest, measured above the waves, is 8,849. Everest is the highest mountain on Earth; Mauna Kea is the tallest."},{"t":"Sports · The Marathon","l":3,"c":"1908","a":["1908","the 1908 London Olympics","London 1908","the 1908 Games"],"s":["The marathon’s odd distance of 26 miles and 385 yards","was fixed for the London Olympics","of","490 BCE."],"w":"The antique run was about 25 miles, and the story attached to it was written up centuries later. The extra 385 yards were added at the 1908 London Olympics so the race could finish in front of the royal box; the distance became official only in 1921."},{"t":"Literature · Frankenstein","l":2,"c":"Victor Frankenstein","a":["Victor Frankenstein","Victor","the scientist","the doctor","the maker","the creator"],"s":["In Mary Shelley’s 1818 novel,","the creature was stitched together by","Henry Clerval,","and haunted by its maker’s rejection ever after."],"w":"Frankenstein is Victor Frankenstein, the student who assembles the creature; the creature itself has no name at all. The mix-up was already old when the book’s first reviewers made it."},{"t":"Food · Fortune Cookies","l":3,"c":"Japan","a":["Japan","Kyoto","a Japanese bakery","Japanese bakers"],"s":["The fortune cookie,","that staple of every Chinese restaurant check,","was invented in","China."],"w":"The folded cookie descends from a Kyoto cracker with a fortune tucked inside, and the modern version was popularized by Japanese immigrant bakeries in California in the early 1900s. Chinese restaurants adopted it decades later; in China it is known, when it is known at all, as an American cookie."},{"t":"Geography · The Capital of Australia","l":2,"c":"Canberra","a":["Canberra"],"s":["When the colonies federated in 1901,","the new national capital was","Melbourne,","and it has never moved since."],"w":"The constitution required a capital in New South Wales but at least a hundred miles from Sydney, so neither Sydney nor Melbourne could win. Canberra, surveyed out of sheep country, received the parliament in 1927."},{"t":"Geography · The Largest Desert","l":3,"c":"Antarctica","a":["Antarctica","the Antarctic","the Antarctic desert"],"s":["The largest hot desert on Earth is the Sahara,","a sea of dunes the size of a continent,","but the largest desert of all is","the sands of the Empty Quarter."],"w":"A desert is measured by rainfall, not sand; Antarctica’s interior receives under 200 millimeters a year and covers about 14 million square kilometers, roughly half again the Sahara. The Sahara is merely the largest hot desert."},{"t":"Food · Chop Suey","l":3,"c":"California","a":["California","San Francisco","New York","America","the United States"],"s":["Chop suey,","the dish every American thinks of as Chinese,","was invented in","China."],"w":"Chop suey, odds and ends in Cantonese, is an American invention of the late 1800s; the dish is unknown in China, and it became known there mostly through tourists asking for it. The stories about it charming a visiting diplomat are themselves tall tales."},{"t":"Space · The North Star","l":3,"c":"Sirius","a":["Sirius","the Dog Star"],"s":["Sailors have trusted the North Star for centuries,","but the brightest star in the night sky","is actually","Polaris."],"w":"Polaris ranks around the fiftieth-brightest star in the night sky; Sirius, the Dog Star, is the brightest by far. The North Star is famous for holding nearly still, not for shining hardest."},{"t":"Invention · The Flush Toilet","l":2,"c":"Sir John Harington","a":["Sir John Harington","John Harington","Harington"],"s":["The flush toilet,","the crowning work of","Thomas Crapper,","was invented in 1596 for Queen Elizabeth I."],"w":"Crapper was a real master plumber who held royal warrants and popularized good fittings, but the flush water closet dates to Harington’s Ajax of 1596, built for Queen Elizabeth I. The word crap was English slang long before either man."},{"t":"Literature · The Deerstalker","l":3,"c":"Sidney Paget","a":["Sidney Paget","Paget","the illustrator","the illustrator Sidney Paget"],"s":["The deerstalker cap and cape,","worn by Sherlock Holmes in the fog,","were put on him by","Arthur Conan Doyle."],"w":"Doyle never puts a deerstalker on Holmes anywhere in the canon; the hat and the curved pipe entered the world in Sidney Paget’s drawings for The Strand Magazine and simply never left."},{"t":"Medicine · The Spanish Flu","l":2,"c":"Kansas","a":["Kansas","the United States","Camp Funston","Haskell County"],"s":["Named for the country that first reported it,","the Spanish flu of 1918","swept out of Spain across a world at war,","killing more people than the trenches ever did."],"w":"Spain was neutral and uncensored, so its newspapers simply told the truth first. The first documented waves came out of Kansas and the American army camps in the spring of 1918, and wartime censorship elsewhere kept the Spanish name."},{"t":"Nature · The Camel","l":1,"c":"North America","a":["North America"],"s":["Ship of the desert for five thousand years,","the camel evolved in the Sahara","and spread with the caravans to every desert,","from Arabia to the Gobi."],"w":"Camels evolved in North America and walked into Asia across the Bering land bridge; the American camels went extinct roughly ten thousand years ago. Australia’s wild dromedaries are feral imports, and the Sahara’s ships are returned immigrants."},{"t":"Clothes · The Panama Hat","l":1,"c":"Ecuador","a":["Ecuador"],"s":["Woven from toquilla straw in the old way,","the Panama hat was born in Panama,","the favorite of gold rush travelers","and presidents at the canal."],"w":"The hats have been woven in Ecuador, around Montecristi and Cuenca, for centuries; Panama only sold them to the world. The name stuck from the 1849 gold rush, when travelers crossed the isthmus and carried the hats home, and Theodore Roosevelt wore one at the canal in 1906."},{"t":"Food · The Caesar Salad","l":2,"c":"Caesar Cardini","a":["Caesar Cardini","Cardini","Cesare Cardini"],"s":["Crisp romaine, coddled egg, and parmesan,","the Caesar salad was invented by","Julius Caesar","at a table in Tijuana."],"w":"Caesar Cardini, an Italian immigrant restaurateur, tossed the first one at his restaurant in Tijuana in 1924, on a busy Fourth of July running short of supplies. The name is his, not the emperor’s; Rome never tasted it."},{"t":"Biology · The Tongue Map","l":3,"c":"a mistranslation","a":["a mistranslation","a mistranslated paper","a misreading","a bad translation"],"s":["The tongue map,","with sweet at the tip and bitter at the back,","was the work of","modern science."],"w":"The map came from a misread 1901 German paper and was cemented by textbook diagrams, but taste buds of every kind sit on every region of the tongue. Taste the same sugar at the tip and at the back: it registers in both, just slightly weaker."},{"t":"Physics · The Old Window","l":3,"c":"wrong","a":["wrong","proved wrong","proved them wrong"],"s":["Medieval window panes run thicker at the bottom","because glass is a slow-flowing liquid,","say the guides on every cathedral tour, and physics has proved them","right."],"w":"Glass is an amorphous solid, rigid at room temperature. Old panes are thick at the bottom because crown-glass makers left one edge heavier, and glaziers installed the heavy side down for stability. Nothing flows on the timescale of cathedrals."},{"t":"Nature · The Ostrich","l":2,"c":"runs","a":["runs","runs away","sprints","flees"],"s":["When a predator closes in,","the ostrich, fastest of birds on two legs,","buries its head in the sand","until the lion loses interest."],"w":"No ostrich buries its head; the bird would suffocate, and an animal that sprints at seventy kilometers an hour has better options. The image probably comes from adults shading their ground nests, heads down over the eggs."},{"t":"History · The First Women Voters","l":3,"c":"1869","a":["1869","eighteen sixty-nine"],"s":["The first American state to let women vote","was Wyoming,","back in","1920."],"w":"Wyoming Territory granted women the vote in 1869, half a century before the Nineteenth Amendment made it national in 1920. A territory that wanted settlers knew a draw when it saw one."},{"t":"Egypt · The Pyramid Builders","l":2,"c":"paid workers","a":["paid workers","paid laborers","free workers","Egyptian laborers","workers"],"s":["Two million blocks, twenty years of labor,","and the pyramids of Giza were raised by","slaves taken in war","for the glory of the kings."],"w":"The builders were recruited Egyptian laborers paid in bread, beer, and status, housed in excavated villages near the plateau with bakeries, breweries, and medical care written in their bones. Slaves did not build the pyramids; Herodotus’s rumor and Hollywood did that stonework."},{"t":"Biology · The Five Senses","l":3,"c":"more than five","a":["more than five","more","at least nine","nine or more","many more"],"s":["The human body meets the world","through its senses,","of which there are","five."],"w":"Balance, temperature, pain, body position, and the sense of your own joints all report without touching anything; researchers count anywhere from nine to twenty-one senses. Aristotle’s tidy five survive because they are the ones with obvious organs."},{"t":"Science · Physics","l":1,"c":"Isaac Newton","a":["Isaac Newton","Newton","Sir Isaac Newton"],"s":["The three laws of motion were formulated by","Albert Einstein","and published in 1687 in the Principia Mathematica,","the most influential physics book ever written."],"w":"It was Isaac Newton. Einstein was born in 1879, nearly two centuries after the Principia; his own revolution came with relativity in 1905."},{"t":"Music · Opera","l":1,"c":"Georges Bizet","a":["Georges Bizet","Bizet"],"s":["The opera Carmen was composed by","Richard Wagner","and premiered in Paris in 1875,","where its first audiences were cool to it."],"w":"It was Georges Bizet, who died three months after the premiere, at thirty-six, believing the work a failure."},{"t":"Art · Baroque","l":1,"c":"Rembrandt","a":["Rembrandt","Rembrandt van Rijn","Rembrandt Harmenszoon van Rijn"],"s":["The Night Watch was painted by","Peter Paul Rubens","in 1642,","and hangs today in the Rijksmuseum in Amsterdam."],"w":"It was Rembrandt, in 1642. Rubens was painting in Antwerp and died two years before it was finished."},{"t":"Literature · Novels","l":1,"c":"Jane Austen","a":["Jane Austen","Austen"],"s":["Pride and Prejudice was written by","Charlotte Brontë","and published in 1813,","when novels still traveled under pen names."],"w":"It was Jane Austen, published anonymously at first, as by a lady. Charlotte Brontë was born two years after it came out."},{"t":"Science · Genetics","l":1,"c":"Gregor Mendel","a":["Gregor Mendel","Mendel","Gregor Johann Mendel"],"s":["The laws of heredity were first worked out by","Charles Darwin","from experiments breeding pea plants in a monastery garden,","years before the gene had a name."],"w":"It was Gregor Mendel, counting pea plants in Brno between 1856 and 1863. Darwin published On the Origin of Species without ever knowing the mathematics that would one day ground it."},{"t":"Geography · Rivers","l":2,"c":"the Atlantic Ocean","a":["the Atlantic Ocean","the Atlantic","Atlantic Ocean"],"s":["The Amazon, the largest river by volume on Earth, flows east across a continent","and empties into","the Pacific Ocean,","where its mouth at Belem is so wide that ocean-going ships sail inland."],"w":"It empties into the Atlantic. The Pacific is on the other side of the continent; Belem sits near the Amazon’s mouth facing the Atlantic."},{"t":"History · Rome","l":3,"c":"Nero","a":["Nero","Emperor Nero"],"s":["In July of 64 CE, a fire broke out near the Circus Maximus and burned for six days,","and the emperor who, legend says, fiddled while the city burned,","though the tale is doubted and the fiddle had not been invented,","was Julius Caesar."],"w":"It was Nero, who was emperor from 54 to 68. Caesar had been dead for nearly a century, and the fiddle itself would not exist for another thousand years; the whole tale is a later rumor."},{"t":"Aviation · Firsts","l":1,"c":"Charles Lindbergh","a":["Charles Lindbergh","Lindbergh","Charles A. Lindbergh"],"s":["The first solo nonstop flight across the Atlantic was made by","Amelia Earhart","in 1927, flying from New York to Paris","against a field of rival aviators."],"w":"It was Charles Lindbergh, in the Spirit of St. Louis, May 1927. Earhart became the first woman to fly solo across the Atlantic five years later."},{"t":"Science · Chemistry","l":1,"c":"Dmitri Mendeleev","a":["Dmitri Mendeleev","Mendeleev","Dmitri Ivanovich Mendeleev","Dmitri Mendeleyev"],"s":["The periodic table of the elements was first published by","Antoine Lavoisier","in 1869, arranging the elements by atomic weight,","in a form chemists still recognize."],"w":"It was Dmitri Mendeleev. Lavoisier, guillotined in 1794, gave chemistry its naming rules and the conservation of mass, but died decades before anyone could count the elements well enough to sort them."},{"t":"Literature · Drama","l":1,"c":"William Shakespeare","a":["William Shakespeare","Shakespeare"],"s":["The play Hamlet was written by","Christopher Marlowe","around 1600 and set in the court of Denmark,","its prince among the most quoted figures in literature."],"w":"It was William Shakespeare. Marlowe had been dead since 1593, and his Edward II is the closest his hand got to Hamlet’s Denmark."},{"t":"History · America","l":1,"c":"Thomas Jefferson","a":["Thomas Jefferson","Jefferson"],"s":["The Declaration of Independence was drafted chiefly by","John Adams","as part of a committee of five appointed in June 1776,","with editing by the whole Congress."],"w":"It was Thomas Jefferson, at thirty-three the youngest of the five. Adams chose him for it, pushed the resolution that made it necessary, and said so for the rest of his life."},{"t":"Music · Symphonies","l":1,"c":"Ludwig van Beethoven","a":["Ludwig van Beethoven","Beethoven","Ludwig Beethoven","van Beethoven"],"s":["The Ninth Symphony, the Choral, with its setting of the Ode to Joy was composed by","Joseph Haydn","and premiered in Vienna in 1824,","its finale a hymn to human brotherhood."],"w":"It was Beethoven, deaf and unable to hear the applause he had to be turned around to see. Haydn died in 1809, fifteen years before that premiere."},{"t":"Geography · Mountains","l":3,"c":"Mount Everest","a":["Mount Everest","Everest","Mt Everest","Mt. Everest"],"s":["The tallest mountain above sea level on Earth,","at 8,849 meters,","on the border of Nepal and China,","is K2."],"w":"It is Everest, at 8,849 meters in the 2020 survey. K2, the second mountain, is more than two hundred meters shorter."},{"t":"History · Exploration","l":1,"c":"Vasco da Gama","a":["Vasco da Gama","Vasco de Gama","da Gama"],"s":["The first European to reach India by sailing around Africa was","Christopher Columbus","landing at Calicut in 1498,","at the close of a decade of ocean voyages."],"w":"It was Vasco da Gama, who reached Calicut in May 1498. Columbus, sailing west the same decade, went to his grave insisting he had found the Indies himself."},{"t":"Science · Astronomy","l":3,"c":"Saturn","a":["Saturn"],"s":["The planet famous for its broad, bright rings,","most of them ice fragments orbiting in a wide sheet,","visited by the Cassini spacecraft for over a decade,","is Jupiter."],"w":"It is Saturn. Jupiter has rings too, but they are thin, dark and almost invisible; Saturn’s are broad sheets of ice visible through small telescopes."},{"t":"Math · The Number Zero","l":1,"c":"India","a":["India","Indian mathematicians"],"s":["The number zero, written as a digit and used as a number you can calculate with,","was invented in","ancient Greece,","and reached Europe through Arabic translations of Greek texts."],"w":"It’s India. Brahmagupta laid down the rules for calculating with zero in 628 CE, and Greek mathematics ran for centuries without any such symbol; the zero Europe adopted arrived in Arabic translations of Indian work."},{"t":"Medicine · The First Vaccine","l":2,"c":"Edward Jenner","a":["Edward Jenner","Jenner","Dr. Edward Jenner"],"s":["The first vaccine, the one for smallpox, was created in 1796","when","Louis Pasteur","took matter from a cowpox sore and scratched it into a boy’s arm."],"w":"It was Edward Jenner, who inoculated eight-year-old James Phipps with cowpox and proved the boy immune to smallpox. Pasteur, born the year before Jenner died, later named the whole art vaccination in the country doctor’s honor."},{"t":"Tech · The First Programmable Computer","l":2,"c":"Konrad Zuse","a":["Konrad Zuse","Zuse","Konrad Zuse the German engineer"],"s":["The first working programmable computer ran in 1941,","built by","Alan Turing,","who used it at Bletchley Park to break German naval codes."],"w":"It was Konrad Zuse, whose electromechanical Z3 ran programs in a Berlin apartment while the war went on around it. Turing’s codebreaking ran on electromechanical bombes, not stored-program computers, and the ENIAC, the machine usually named first, followed in 1945."},{"t":"Space · The Moons of Jupiter","l":1,"c":"Galileo Galilei","a":["Galileo Galilei","Galileo"],"s":["The four large moons of Jupiter were discovered by","Johannes Kepler,","with the telescope he built in 1610,","and named for the Medici family of Florence."],"w":"It was Galileo Galilei, who turned an improved telescope on Jupiter in January 1610 and found four wandering stars. Kepler was a theorist who barely observed, and the moons were named for the Medici precisely because Galileo was courting a patron."},{"t":"Literature · The Divine Comedy","l":1,"c":"Dante Alighieri","a":["Dante Alighieri","Dante"],"s":["The Divine Comedy, the tour of Hell, Purgatory and Paradise, was written by","Giovanni Boccaccio,","in the Italian vernacular,","and finished in 1321, the year of its author’s death."],"w":"It was Dante Alighieri, who finished the poem in exile from Florence in 1321; Boccaccio was then a child of eight, and grew up to lecture on Dante’s poem rather than write it."},{"t":"Music · The Four Seasons","l":1,"c":"Antonio Vivaldi","a":["Antonio Vivaldi","Vivaldi"],"s":["The Four Seasons, the violin concertos that paint birdsong and storms, were composed by","Johann Sebastian Bach,","and published in Amsterdam in 1725,","winning a contest among Italian virtuosos."],"w":"It was Antonio Vivaldi, the Venetian priest, whose Opus 8 came out in Amsterdam in 1725; Bach studied Vivaldi’s concertos to learn the Italian style, and arranged several for harpsichord and organ."},{"t":"Art · The Sistine Chapel","l":2,"c":"Michelangelo","a":["Michelangelo","Michelangelo Buonarroti"],"s":["The Sistine Chapel ceiling, painted from 1508 to 1512,","was painted by","Leonardo da Vinci,","lying flat on his back on scaffolding of his own design."],"w":"It was Michelangelo, who painted standing with his head tipped back on scaffolding he helped design, and who called himself a sculptor, not a painter. Leonardo had abandoned his own mural across town years before the first plank went up."},{"t":"Geography · The Deepest Lake","l":3,"c":"Lake Baikal","a":["Lake Baikal","Baikal"],"s":["The deepest lake on Earth, more than sixteen hundred meters to its floor,","holding a fifth of the planet’s fresh surface water,","sits in a rift valley of Siberia,","and is called Lake Tanganyika."],"w":"It is Lake Baikal, the Siberian rift lake at 1,642 meters; Tanganyika in Africa is the second deepest, and the longer of the two."},{"t":"History · The Norman Conquest","l":3,"c":"1066","a":["1066","ten sixty-six"],"s":["The Norman Conquest of England, when Duke William crossed the Channel,","took the kingdom at Hastings with an arrow to the king’s eye,","and ended Anglo-Saxon rule,","in the year 1016."],"w":"It was 1066, the one date every English schoolchild carries. 1016 belongs to Cnut, whose Danish conquest had come and gone half a century before the Normans landed."},{"t":"Food · The Sandwich","l":2,"c":"John Montagu","a":["John Montagu","the Earl of Sandwich","the fourth Earl of Sandwich"],"s":["The sandwich, as the story goes, took its name in the 1760s","from","the Duke of Wellington,","who ordered meat between bread so he could keep gambling without leaving the table."],"w":"It was John Montagu, the fourth Earl of Sandwich, whose gambling table the story belongs to. Wellington gives his name to the boot and the beef dish, a generation later and a different table entirely."},{"t":"Sports · The First World Cup","l":3,"c":"1930","a":["1930","nineteen thirty"],"s":["The first World Cup of association football,","won outright by the host country in its new Centenario stadium,","with thirteen teams, several of whom crossed the Atlantic on the same steamship,","took place in 1926."],"w":"It took place in 1930, in Uruguay, which built the Centenario for the occasion and won it without needing a playoff. 1926 is four years and a world of argument early; FIFA had not even voted to hold the thing yet."},{"t":"Mythology · Thor’s Hammer","l":3,"c":"Mjolnir","a":["Mjolnir","Mjölnir","Mjollnir"],"s":["In Norse myth, the thunder god’s hammer,","forged by dwarven smiths and short one hand’s width of handle,","returns to the thrower’s grip and levels mountains,","and its name is Gram."],"w":"It is Mjolnir, the crusher; Gram is the sword of Sigurd the dragon slayer, a different treasure from a different legend, and the two never share a saga."},{"t":"Math · The Pythagorean Theorem","l":3,"c":"the Babylonians","a":["the Babylonians","Babylonians","Babylonian scribes"],"s":["The theorem about the squares on the sides of a right triangle,","which schoolchildren learn under the name of Pythagoras,","was in use long before the Greek was born,","having been discovered by medieval algebraists around the year 1300."],"w":"It was the Babylonians. The tablet Plimpton 322, written around 1800 BCE, lists whole-number triples fitting the theorem more than a thousand years before Pythagoras; the Greeks supplied the proof, not the discovery."},{"t":"Medicine · Blood Circulation","l":0,"c":"William Harvey","a":["William Harvey","Harvey","Dr. William Harvey"],"s":["Galen,","the physician of the second century,","proved that blood circulates in a closed loop","pumped around by the heart."],"w":"It was William Harvey, whose 1628 treatise measured how much blood the heart moves and argued that it must go round and round. Galen taught that blood was made in the liver and burned up like fuel, and medicine stood by him for fourteen hundred years."},{"t":"Tech · The QWERTY Keyboard","l":1,"c":"Christopher Latham Sholes","a":["Christopher Latham Sholes","Sholes","C. Latham Sholes"],"s":["The QWERTY keyboard layout was created by","Henry Dreyfuss,","the American industrial designer,","for the typewriter of the 1870s."],"w":"It was Christopher Latham Sholes, the Milwaukee newspaperman who invented the typewriter, tuning the layout through the 1870s as the machine evolved. Dreyfuss, born in 1904, redesigned telephones and thermostats; he never touched a keyboard."},{"t":"Space · The Big Bang","l":1,"c":"Georges Lemaître","a":["Georges Lemaître","Georges Henri Lemaître","Lemaître","Lemaitre"],"s":["The expanding-universe theory now called the Big Bang was first proposed by","Edwin Hubble,","after measuring the recession of the galaxies","at Mount Wilson in 1929."],"w":"It was Georges Lemaître, a Belgian priest and physicist, who derived the expanding universe from Einstein’s equations in 1927 and called its origin the primeval atom. Hubble supplied the measurements that convinced the world, two years after the physics."},{"t":"Literature · Don Quixote","l":1,"c":"Miguel de Cervantes","a":["Miguel de Cervantes","Cervantes","Miguel Cervantes"],"s":["Don Quixote, the first great novel of the modern kind, was written by","Lope de Vega,","Spain’s phenomenally prolific playwright,","who began it in a Seville jail in 1597."],"w":"It was Miguel de Cervantes, who likely conceived the book during a Seville imprisonment and published it in 1605. Lope de Vega, his rival with plays by the hundred, mocked the aging soldier in verse and never wrote the book that invented the modern novel."},{"t":"Music · Aida","l":2,"c":"Giuseppe Verdi","a":["Giuseppe Verdi","Verdi"],"s":["The opera Aida, set in ancient Egypt, premiered in Cairo in 1871","and was composed by","Richard Wagner,","for the celebrations that opened the Suez Canal."],"w":"It was Giuseppe Verdi, writing for the khedive’s new opera house in Cairo. The Suez Canal opened in 1869 without an opera, and Wagner never set a note in Egypt; he was in Germany at work on his Ring."},{"t":"Art · The School of Athens","l":2,"c":"Raphael","a":["Raphael","Raffaello Sanzio","Raffaello"],"s":["The School of Athens, the fresco that gathers Plato and Aristotle under a great arch,","was painted by","Michelangelo,","in the Pope’s own apartments in the Vatican."],"w":"It was Raphael, who frescoed the papal rooms between 1509 and 1511 while Michelangelo was vaulting the Sistine Chapel a corridor away. Raphael peeked at the sealed chapel, and slipped the grumbling master into his scene as the sulking Heraclitus."},{"t":"Geography · The Highest Waterfall","l":3,"c":"Angel Falls","a":["Angel Falls","Angel Falls in Venezuela","Salto Ángel"],"s":["The highest uninterrupted waterfall on Earth, dropping almost a kilometer from a table mountain,","named for an American pilot who scouted it from the air in the 1930s,","lies in the rainforest of Venezuela,","and is called Niagara Falls."],"w":"It is Angel Falls, the Salto Ángel, which drops 979 meters from the Auyán Tepui. Niagara is the famous waterfall, but its sheer drop is about fifty meters, and its fame is volume, not height."},{"t":"History · The Hundred Years War","l":3,"c":"116 years","a":["116 years","one hundred sixteen years","a hundred sixteen years"],"s":["The Hundred Years War between England and France,","fought from the sea battle of Sluys to the fall of Bordeaux,","ran on and off across five generations,","and lasted exactly one hundred years."],"w":"It lasted 116 years, from 1337 to 1453. The round number was never a stopwatch; the name was a chronicler’s shorthand that stuck, and the war outlived many of its soldiers."},{"t":"Food · Tea","l":3,"c":"China","a":["China","ancient China","southeastern China"],"s":["The tea plant, source of the most drunk beverage on Earth after water,","first cultivated in the hills where its wild trees still stand,","carried out along caravan and ocean routes to every country,","originated in India."],"w":"It originated in China, in the hill country of Yunnan where wild tea trees still grow. India’s vast plantations are a nineteenth-century British creation, seeded with Chinese plants shipped out in secret, along with Chinese growers to teach the craft."},{"t":"Sports · The Tour de France","l":3,"c":"1903","a":["1903","nineteen three","nineteen oh three"],"s":["The Tour de France, the three-week race around the country,","launched by a struggling sports paper to sell copies,","and won by Maurice Garin by nearly three hours in its first running,","began in 1919."],"w":"It began in 1903, as a circulation stunt for the newspaper L’Auto; 1919 is the year the race first dressed its leader in yellow, after the war had silenced it for five seasons."},{"t":"Math · Calculus","l":1,"c":"Gottfried Wilhelm Leibniz","a":["Gottfried Wilhelm Leibniz","Leibniz","Wilhelm Leibniz"],"s":["Calculus was first published by","Isaac Newton,","who put it in the Principia of 1687","and defended his priority against every rival."],"w":"It was Gottfried Wilhelm Leibniz, whose 1684 paper on differentials reached print three years before the Principia and two decades before Newton let his fluxions see daylight. Newton had the ideas early but kept them to himself; the priority war that followed set English mathematics back a century."},{"t":"Medicine · Handwashing","l":1,"c":"Ignaz Semmelweis","a":["Ignaz Semmelweis","Semmelweis","Dr. Ignaz Semmelweis"],"s":["That doctors should wash their hands between patients, with mortality figures to prove it, was first urged by","Florence Nightingale,","the reformer of battlefield nursing,","during the Crimean War of the 1850s."],"w":"It was Ignaz Semmelweis, at a Vienna hospital in 1847, who showed that washing in chlorinated lime cut the childbed fever that killed new mothers, after noticing that wards run by students straight from autopsies fared worst. Nightingale, campaigning a decade later, made cleanliness a creed, but the data came first from Vienna."},{"t":"Tech · The First Text Message","l":3,"c":"1992","a":["1992","nineteen ninety-two"],"s":["The first SMS text message, reading simply Merry Christmas,","was sent from a computer to a telephone","over a test network in Britain,","in 1973."],"w":"It was 1992, when Neil Papworth typed the greeting to an Orbitel phone three days before Christmas. 1973 was the year of the first handheld mobile call, two decades before a phone could carry anything but voice."},{"t":"Space · Halley’s Comet","l":2,"c":"Edmond Halley","a":["Edmond Halley","Halley","Edmund Halley"],"s":["Halley’s Comet, which returns to our skies every seventy-six years or so,","was predicted to return by","Isaac Newton,","who spotted the pattern in the records of 1531, 1607 and 1682."],"w":"It was Edmond Halley, who identified three recorded comets as one visitor and staked his reputation on a 1758 return he did not live to see. Newton supplied the mathematics of orbits; the daring leap of the prediction belongs to his friend."},{"t":"Literature · War and Peace","l":2,"c":"Leo Tolstoy","a":["Leo Tolstoy","Tolstoy","Lev Tolstoy","Count Tolstoy"],"s":["War and Peace, published in installments through the 1860s,","was written by","Fyodor Dostoevsky,","who filled it with the salons of St Petersburg and the battlefields of 1812."],"w":"It was Leo Tolstoy, who set his epic against Napoleon’s invasion and rewrote it for years; Dostoevsky’s Russia was the Petersburg of schemers and students, the world of Crime and Punishment, which he was writing at the same time."},{"t":"Music · The Magic Flute","l":1,"c":"Wolfgang Amadeus Mozart","a":["Wolfgang Amadeus Mozart","Mozart","W. A. Mozart"],"s":["The opera The Magic Flute, with the Queen of the Night’s impossible high notes, was composed by","Joseph Haydn,","and premiered in Vienna in 1791,","weeks before its composer’s death."],"w":"It was Wolfgang Amadeus Mozart, who conducted the premiere and died that December. Haydn, his older friend, was in London through most of that year, and the opera’s jokes belong to Mozart’s own Masonic lodge in Vienna."},{"t":"Art · Impression, Sunrise","l":1,"c":"Claude Monet","a":["Claude Monet","Monet"],"s":["Impression, Sunrise, the harbor view that gave Impressionism its name, was painted by","Édouard Manet,","and hung in the 1874 Paris exhibition","where a critic’s sneer named the movement."],"w":"It was Claude Monet, whose 1872 view of boats at Le Havre hung in that first show; a critic seized on its title to mock a whole exhibition of impressionist painting. Manet, the movement’s forerunner, kept his distance and kept sending works to the official Salon."},{"t":"Geography · The Largest Country","l":3,"c":"Russia","a":["Russia","the Russian Federation"],"s":["The largest country on Earth, spanning eleven time zones,","covering more than a tenth of the world’s land,","stretching from the Baltic to the Bering Strait,","is Canada."],"w":"It is Russia, at almost twice Canada’s area. Canada is the second largest, the giant of the Western Hemisphere, and holds the longest coastline on the planet."},{"t":"History · China’s First Emperor","l":3,"c":"Qin Shi Huang","a":["Qin Shi Huang","Qin Shihuangdi","Shi Huangdi","Ying Zheng"],"s":["The first emperor of a unified China,","who standardized the script, the coinage and the axle widths,","and was buried beside an army of clay soldiers,","was Kublai Khan."],"w":"It was Qin Shi Huang, who unified the warring states by 221 BCE and left his name to the country; Kublai Khan conquered China from Mongolia a millennium and a half later, founding a foreign dynasty on top of an old story."},{"t":"Sports · The First Super Bowl","l":3,"c":"1967","a":["1967","nineteen sixty-seven"],"s":["The first Super Bowl, then billed as the AFL-NFL World Championship Game,","between Green Bay and Kansas City,","televised by two networks at once,","was played in 1957."],"w":"It was played in January 1967, when the Packers won in Los Angeles, a decade before the leagues merged. The name came later, borrowed, so the story goes, from a child’s bouncy Super Ball, and it never left."},{"t":"Space · The First Woman in Space","l":1,"c":"Valentina Tereshkova","a":["Valentina Tereshkova","Tereshkova"],"s":["The first woman to fly in space was","Sally Ride,","who orbited the Earth for three days","aboard Vostok 6 in 1963."],"w":"It was Valentina Tereshkova, a Soviet factory worker and amateur parachutist, who spent almost three days in orbit in June 1963. Sally Ride flew on the space shuttle in 1983, twenty years later, as the first American woman in space."},{"t":"Literature · The Raven","l":1,"c":"Edgar Allan Poe","a":["Edgar Allan Poe","Edgar Allen Poe","Poe"],"s":["The poem The Raven, with its midnight visitor and its one repeated word, was written by","Henry Wadsworth Longfellow,","and published in 1845,","making its author famous across America overnight."],"w":"It was Edgar Allan Poe, who sold the poem for a few dollars in 1845 and watched it make his name in weeks. Longfellow was the respectable poet of the age, whom Poe accused in print of plagiarism while never matching the raven’s grip."},{"t":"Music · The 1812 Overture","l":1,"c":"Pyotr Ilyich Tchaikovsky","a":["Pyotr Ilyich Tchaikovsky","Tchaikovsky","Peter Tchaikovsky"],"s":["The 1812 Overture, with its cannon fire and ringing bells, was composed by","Dmitri Shostakovich,","for the commemoration of Napoleon’s retreat,","in the middle of the Second World War."],"w":"It was Pyotr Ilyich Tchaikovsky, who wrote it in 1880 for the consecration of a Moscow cathedral and privately called the piece loud and noisy without much artistic merit. Shostakovich was born in 1906, a dozen years after Tchaikovsky died."},{"t":"Art · The Birth of Venus","l":1,"c":"Sandro Botticelli","a":["Sandro Botticelli","Botticelli","Alessandro Filipepi"],"s":["The Birth of Venus, the goddess standing on a shell in the sea wind, was painted by","Titian,","for the Medici circle in Florence,","in the early 1480s."],"w":"It was Sandro Botticelli, painting for the Medici’s circle around 1485; Titian was not yet born, and his Venuses belong to Venice a lifetime later, fuller figures in richer color."},{"t":"Geography · The Most Populous Country","l":3,"c":"India","a":["India","the Republic of India"],"s":["The most populous country on Earth,","past one point four billion people,","counted past its great rival by United Nations estimates in 2023,","is China."],"w":"It is India, which passed China in 2023 by the UN count, ending China’s long run at the top. India’s population is still climbing while China’s has begun to shrink, so the gap only grows."},{"t":"History · The Fall of Constantinople","l":3,"c":"1453","a":["1453","fourteen fifty-three"],"s":["The fall of Constantinople to the Ottoman siege,","when a great cannon opened the Theodosian walls,","ended the Byzantine Empire after eleven centuries,","in the year 1492."],"w":"It was 1453. 1492 is the year of Columbus and Granada; by then Constantinople had been Ottoman for a generation, and its Greek scholars had long carried their books west into Italy."},{"t":"Tech · Linux","l":2,"c":"Linus Torvalds","a":["Linus Torvalds","Torvalds"],"s":["The Linux kernel was released in 1991","by","Richard Stallman,","who announced it as a hobby project from a student’s room."],"w":"It was Linus Torvalds, a Finnish student whose hobby announcement became the kernel at the heart of nearly everything. Stallman launched GNU, whose tools and licence Linux adopted, and he has policed the distinction ever since."},{"t":"Space · Measuring Light","l":1,"c":"Ole Rømer","a":["Ole Rømer","Ole Roemer","Rømer","Romer"],"s":["The speed of light was first measured, using the moons of Jupiter, by","Galileo Galilei,","who clocked it with lantern signals","between hills outside Florence."],"w":"It was Ole Rømer, a Danish astronomer who noticed in 1676 that Jupiter’s moon Io ran late as Earth moved farther away, and turned the lag into a speed. Galileo did try lanterns on hills and honestly concluded light was too fast to catch."},{"t":"Literature · The Odyssey","l":0,"c":"Homer","a":["Homer","Homer the bard"],"s":["Virgil,","the blind bard of the Greek islands, is credited with the Odyssey,","the long journey home from Troy,","which singers carried for centuries before it was written down."],"w":"It is Homer, the Greek bard of the tradition; Virgil was a Roman poet, born seven centuries later, who deliberately answered the Greek epics with his Aeneid."},{"t":"Music · The Entertainer","l":1,"c":"Scott Joplin","a":["Scott Joplin","Joplin"],"s":["The ragtime piano piece The Entertainer was written by","Duke Ellington,","and published in 1902,","long before it resurfaced in the saloons of New Orleans."],"w":"It was Scott Joplin, the king of ragtime, who published it in 1902; Ellington was a toddler of three that year. The piece resurfaced not in New Orleans but on movie screens of the 1970s, when its sheet music again outsold nearly everything."},{"t":"Art · The Starry Night","l":1,"c":"Vincent van Gogh","a":["Vincent van Gogh","Van Gogh","van Gogh"],"s":["The Starry Night, the swirling sky over a sleeping town, was painted by","Paul Gauguin,","from a window at the asylum at Saint-Rémy,","in 1889, a year before the painter’s death."],"w":"It was Vincent van Gogh, who painted the view, partly from memory, at Saint-Rémy in June 1889. Gauguin had stayed with him in Arles the winter before, the visit that ended in van Gogh’s breakdown, but by that June he was painting in Brittany."},{"t":"Geography · The Source of the Nile","l":3,"c":"Lake Victoria","a":["Lake Victoria","Victoria","the Victoria Nyanza"],"s":["The White Nile, the longest branch of the longest river on Earth,","traced at last by European expeditions in the nineteenth century,","is counted as beginning at","Lake Chad."],"w":"It is Lake Victoria, the outflow at Jinja in Uganda, honored since the expeditions of the 1860s. Hydrologists still argue for more distant springs in Burundi and Rwanda that feed the lake itself, but the classic answer stands on the maps."},{"t":"History · The French Revolution","l":3,"c":"1789","a":["1789","seventeen eighty-nine"],"s":["The French Revolution, the storming of the Bastille and the fall of the old order,","sparked by bread riots and a bankrupt treasury,","toppled the monarchy and shook every throne in Europe,","and began in the year 1804."],"w":"It began in 1789, with the Bastille falling on the fourteenth of July. 1804 is the year Napoleon crowned himself emperor, which is what the revolution ended up producing at the far end of its story."},{"t":"Tech · The Transistor","l":3,"c":"1947","a":["1947","nineteen forty-seven"],"s":["The transistor, the switch at the heart of every chip,","was demonstrated at Bell Laboratories in New Jersey,","by Bardeen, Brattain and Shockley,","in 1937."],"w":"It was 1947, in the week before Christmas, that the first point-contact transistor amplified a signal. 1937 belongs to earlier patents that never built a working device; the integrated circuit, which wired transistors together, came a decade later."},{"t":"Space · The Planet Past Neptune","l":1,"c":"Clyde Tombaugh","a":["Clyde Tombaugh","Tombaugh"],"s":["The world now called Pluto, once counted as the ninth planet, was discovered by","Percival Lowell,","who spent his last years","scanning photographic plates under Arizona skies."],"w":"It was Clyde Tombaugh, a Kansas farm boy hired for the plate work, who found Pluto in 1930, fourteen years after Lowell died. Lowell had predicted a planet several times heavier than Earth; the found object was far too small to be his Planet X, a coincidence later generations proved."},{"t":"Literature · Paradise Lost","l":0,"c":"John Milton","a":["John Milton","Milton"],"s":["William Shakespeare","wrote Paradise Lost, the epic of Adam and Eve’s fall,","dictating it after losing his sight,","and published it in 1667."],"w":"It was John Milton, who composed the poem largely in his head and dictated it to helpers, publishing in 1667 half a century after Shakespeare died in 1616."},{"t":"Music · West Side Story","l":1,"c":"Leonard Bernstein","a":["Leonard Bernstein","Bernstein","Lenny Bernstein"],"s":["The musical West Side Story, Romeo and Juliet set in New York, was written by","Cole Porter,","with dances by Jerome Robbins,","and premiered on Broadway in 1957."],"w":"It was Leonard Bernstein, who wrote the 1957 score, with the young Stephen Sondheim supplying the lyrics in his Broadway debut. Porter’s golden era was the 1930s, and he had written little for years when it opened."},{"t":"Literature · Les Misérables","l":1,"c":"Victor Hugo","a":["Victor Hugo","Hugo"],"s":["Les Misérables was written by","Émile Zola,","the French novelist of the slums,","and published from exile on Guernsey in 1862."],"w":"It was Victor Hugo, who wrote it on Guernsey, where he had fled the regime of Napoleon the Third. Zola was twenty-two when it appeared, still writing reviews; the novels it gets confused with came a decade later."},{"t":"Geography · The Oldest Republic","l":3,"c":"San Marino","a":["San Marino","the Republic of San Marino"],"s":["The oldest republic still standing in the world,","founded, by its own tradition, by a stonecutter fleeing persecution in Rome,","governed by statutes dating to the year 1600,","is the United States of America."],"w":"It is San Marino, the mountain republic whose founding tradition reaches to 301 CE and whose statutes of 1600 read like a constitution. The American republic is a mere quarter of a millennium old, though it does hold the oldest single written constitution still in force."},{"t":"History · The Oldest University","l":3,"c":"Bologna","a":["Bologna","the University of Bologna","Bologna in Italy"],"s":["The oldest university in continuous operation,","teaching law to students who elected their own professors,","with a founding tradition of 1088,","stands in Paris."],"w":"It is Bologna, the Italian studium where the students formed the guild and hired their masters; Paris and Oxford are of comparable antiquity, but Bologna kept the records that made the university a self-governing thing."},{"t":"Tech · The Computer Mouse","l":1,"c":"Douglas Engelbart","a":["Douglas Engelbart","Engelbart","Doug Engelbart"],"s":["The computer mouse was invented and demonstrated by","Steve Wozniak,","who built the first one","in the garage where Apple began."],"w":"It was Douglas Engelbart, who showed the mouse in his 1968 demonstration of windows, links and screensharing, an hour of the future in one sitting. Wozniak’s garage belongs to Apple, founded in 1976; the mouse Engelbart’s team carved had existed since 1964."},{"t":"Literature · The First Novel","l":0,"c":"Murasaki Shikibu","a":["Murasaki Shikibu","Murasaki","Lady Murasaki"],"s":["A Chinese court official","wrote the Tale of Genji, often called the world’s first novel,","around the year 1000,","in classical Chinese for the emperor’s reading."],"w":"It was Murasaki Shikibu, a Japanese court lady writing in her own vernacular around 1008, whose long story of a shining prince stands alone for centuries before anything like it in Europe."}];
